const fs = require('fs');
const { execSync } = require('child_process');

// .docx is a zip file; we can use Node's zlib + manual zip parsing,
// but let's try the built-in approach with a lightweight unzip via yauzl or manual parsing.

// Manual ZIP parsing for the word/document.xml entry
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');
const zlib = require('zlib');

// Find local file headers (PK\x03\x04)
const entries = [];
let offset = 0;
while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) === 0x04034b50) {
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.toString('utf8', offset + 30, offset + 30 + nameLen);
    const dataStart = offset + 30 + nameLen + extraLen;
    entries.push({ name, compMethod, compSize, uncompSize, dataStart });
    offset = dataStart + compSize;
  } else {
    offset++;
  }
}

const docEntry = entries.find(e => e.name === 'word/document.xml');
if (!docEntry) { console.log('No word/document.xml found'); process.exit(1); }

let xml;
const raw = buf.slice(docEntry.dataStart, docEntry.dataStart + docEntry.compSize);
if (docEntry.compMethod === 8) {
  xml = zlib.inflateRawSync(raw).toString('utf8');
} else {
  xml = raw.toString('utf8');
}

// Extract text from <w:t> elements
const lines = [];
// Split by paragraph <w:p>
const paragraphs = xml.split(/<w:p[ >]/);
for (const para of paragraphs) {
  const texts = [];
  const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let m;
  while ((m = re.exec(para)) !== null) {
    texts.push(m[1]);
  }
  if (texts.length > 0) {
    lines.push(texts.join(''));
  }
}
console.log(lines.join('\n'));
